class Solution { fun findShortestCycle(n:Int,edges:Array<IntArray>):Int{val graph=Array(n){mutableListOf<Int>()};for(edge in edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0])};var answer=Int.MAX_VALUE;for(source in 0 until n){val distance=IntArray(n){-1};val parent=IntArray(n){-1};val queue=java.util.ArrayDeque<Int>();distance[source]=0;queue.add(source);while(queue.isNotEmpty()){val node=queue.removeFirst();for(next in graph[node]){if(distance[next]<0){distance[next]=distance[node]+1;parent[next]=node;queue.add(next)}else if(parent[node]!=next)answer=minOf(answer,distance[node]+distance[next]+1)}}};return if(answer==Int.MAX_VALUE)-1 else answer} }
